mapper.select:
/*selectMasterCmClSalesTaxExportSumList*/
SELECT GR.BUYER , CMPY.IRS_NO AS BUYER_IRS_NO , CMPY.COM_NAME_LOC AS BUYER_NAME , GR.EXP_GR_NO , GR.EXP_DATE_OF_SHIPMENT , GR.EXP_CUR , GR.EXP_CUR_PRICE , (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = DECODE(GR.BUYER, 'KRKOLO0077', 'KK', 'KA')) AS KEP_IRS_NAME , MAX(CMPY.COM_NAME_LOC) AS BUYER_NAME , MAX(NVL(GR.AR_CLOSE_DEPT, MNG.KEP_DEPT)) AS KEP_DEPT , SUM(ROUND((GR.ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER)))) AS GR_AMT , SUM(GR.EXP_FOR_ITEM_AMT) AS EXP_FOR_ITEM_AMT , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = DECODE(GR.BUYER, 'KRKOLO0077', 'KK', 'KA')) AS KEP_IRS_NO , MAX(GR.AR_CLOSE_DEPT) AS KEP_DEPT_CODE , F_GET_CREDIT_LIMIT_STTS(GR.BUYER,'','','2') AS CREDIT_LIMIT_FLAG , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , MAX(CMPY.SYS_TYPE) AS SITE_GUBUN_CODE FROM ICOMGRDT GR , ICOMPOHD POHD , ICOMPODT PODT , ICOMPRDT PRDT , V_VOC_ICOMCMPY CMPY , ICOMCMPY CM , ICOMBYIT BYIT , ( SELECT DISTINCT BUYER, KEP_DEPT FROM MIS_BUYER_MNG WHERE 1=1 AND YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' ) MNG WHERE 1=1 AND GR.BUYER = CMPY.COM_CODE AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.BUYER = MNG.BUYER AND POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND GR.BUYER = CM.COM_CODE AND CM.BYCA_COMORG_CODE = BYIT.BUYER AND BYIT.BUYER_ITEM_NO = PRDT.BUYER_ITEM_NO AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND BYIT.BUYER_ITEM_NO = GR.BUYER_ITEM_NO AND GR.AR_BILL_FLAG = 'N' AND GR.STATUS <> 'D' AND POHD.DOC_TYPE <> 'X' AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.BUYER NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AR' AND TEXT2 IN ('KA', 'KK')) AND GR.EXP_GR_NO IS NOT NULL
AND GR.BUYER =#{st_buyer_code}
AND GR.AGENT = #{st_agent_code}
AND CMPY.IRS_NO LIKE #{st_irs_no} || '%'
GROUP BY GR.BUYER , CMPY.IRS_NO , CMPY.COM_NAME_LOC , GR.EXP_GR_NO , GR.EXP_DATE_OF_SHIPMENT , GR.EXP_CUR , GR.EXP_CUR_PRICE

mapper.update:
/*insertMasterCmClSalesTaxExportSum_KEPTARDT*/
INSERT INTO KEPTARDT /* 외상매출_세금계산서 */ ( TAX_BILL_NO , KEP_IRS , SITE , DEPT_CODE , STATUS , ISSUE_DATE , CUSTOMER_NAME , IRS_NO , BUYER_CODE
, TOT_SUPP_PRICE , TOT_TAX_PRICE , TOT_AMT , SUPP_PRICE , TAX_PRICE , AMT
, TAX_TYPE , BILL_TYPE , PRINT_DATE , PRINT_USER_ID , PRINT_CNT , PRINT_AVAIL_CNT , CONFIRM_FLAG , REMARK_DESCRIPTION , REMARK_SPECIFICATION , REMARK_QTY , REMARK_PRICE
, ASK_TYPE , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID
, AR_CLOSE_MONTH , AR_CLOSE_REVISION , KEP_IRS_NAME , KEP_CEO_NAME_LOC , KEP_INDUSTRY_TYPE , KEP_BUSINESS_ITEMS , KEP_ADDRESS_LOC , IRS_NAME , CEO_NAME_LOC , INDUSTRY_TYPE , BUSINESS_ITEMS , ADDRESS_LOC , EXP_CUR , EXP_CUR_PRICE , EXP_FOR_ITEM_AMT , EXP_GR_NO , EXP_DATE_OF_SHIPMENT ) VALUES ( #{order_no} , #{KEP_IRS_NO} , 'KA' , #{dept_code} , 'C' , TO_CHAR(LAST_DAY(TO_DATE(#{issue_date},'YYYYMM')),'YYYYMMDD') , #{buyer_irs_name} , #{irs_no} , #{buyer_code} , TRUNC(#{tot_amt}) , 0 , TRUNC(#{tot_amt}) , TRUNC(#{supp_price}) , 0 , TRUNC(#{supp_price}) , '16' /*TAX_TYPE*/ , '10' , '' /*PRINT_DATE*/ , '' /*PRINT_USER_ID*/ , 0 /*PRINT_CNT*/ , 1 /*PRINT_AVAIL_CNT*/ , 'N' /*CONFIRM_FLAG*/ , 'MRO용품외' , 'MRO용품외' , 1 , #{tot_amt}
, '02' /*ASK_TYPE*/ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id} , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , #{st_user_id}
, #{issue_date} , #{st_close_revision} , #{kep_irs_name} , #{kep_ceo_name_loc} , #{kep_industry_type} , #{kep_business_items} , #{kep_address_loc} , #{buyer_irs_name} , #{buyer_ceo_name_loc} , #{buyer_industry_type} , #{buyer_business_items} , #{buyer_address_loc} , #{key_exp_cur} , #{key_exp_cur_price} , #{exp_amt} , #{key_exp_gr_no} , #{key_exp_date} )

/* updateMasterCmClSalesTaxExportSum_KEPTARDT_ORG */

	UPDATE KEPTARDT
	SET		SUPP_PRICE = TOT_SUPP_PRICE - #{it_amt}
	,			TAX_PRICE = 0
	,			AMT = TOT_SUPP_PRICE - #{it_amt}
	,			REMARK_PRICE = TOT_SUPP_PRICE - #{it_amt} 
	WHERE	TAX_BILL_NO = #{ar_no}
